export * as Event from "./event.js";
import { Schema, SchemaTransformation } from "effect";
import { optional } from "./schema.js";
import { ascending } from "./identifier.js";
import { Location } from "./location.js";
import { statics } from "./schema.js";
export const ID = Schema.String.check(Schema.isStartingWith("evt_")).pipe(Schema.brand("Event.ID"), Schema.annotate({ identifier: "Event.ID" }), statics((schema) => ({ create: () => schema.make("evt_" + ascending()) })));
/**
 * Position in one aggregate's durable log. Values originate from the durable
 * event envelope and synced markers;
 * `after` cursors accept only values that came from those sources.
 */
export const Seq = Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)).pipe(Schema.brand("Event.Seq"), Schema.annotate({ identifier: "Event.Seq" }));
/** Durable schema version of one event type, from the event definition that committed it. */
export const Version = Schema.Int.check(Schema.isGreaterThanOrEqualTo(1)).pipe(Schema.brand("Event.Version"), Schema.annotate({ identifier: "Event.Version" }));
const DurableEnvelope = Schema.Struct({ aggregateID: Schema.String, seq: Seq, version: Version });
export function durable(input) {
    const data = Schema.Struct(input.schema);
    const durable = Schema.Struct({
        aggregateID: DurableEnvelope.fields.aggregateID,
        seq: DurableEnvelope.fields.seq,
        version: Schema.Literal(input.durable.version).pipe(Schema.decodeTo(Schema.toType(Version), SchemaTransformation.transform({
            decode: () => Version.make(input.durable.version),
            encode: () => input.durable.version,
        }))),
    });
    return Schema.Struct({
        id: ID,
        created: Schema.Finite,
        metadata: optional(Schema.Record(Schema.String, Schema.Unknown)),
        type: Schema.Literal(input.type),
        durable,
        location: optional(Location.Ref),
        data,
    })
        .annotate({ identifier: input.identifier ?? input.type })
        .pipe(statics(() => ({
        type: input.type,
        durability: "durable",
        durable: input.durable,
        data,
    })));
}
export function ephemeral(input) {
    const data = Schema.Struct(input.schema);
    return Schema.Struct({
        id: ID,
        created: Schema.Finite,
        metadata: optional(Schema.Record(Schema.String, Schema.Unknown)),
        type: Schema.Literal(input.type),
        location: optional(Location.Ref),
        data,
    })
        .annotate({ identifier: input.identifier ?? input.type })
        .pipe(statics(() => ({
        type: input.type,
        durability: "ephemeral",
        durable: undefined,
        data,
    })));
}
export function inventory(...definitions) {
    return Object.freeze(definitions);
}
export function latest(definitions) {
    return readonlyMap(definitions.reduce((result, definition) => {
        const existing = result.get(definition.type);
        if (!existing) {
            result.set(definition.type, definition);
            return result;
        }
        if (definition.durable && existing.durable && definition.durable.version !== existing.durable.version) {
            if (definition.durable.version > existing.durable.version)
                result.set(definition.type, definition);
            return result;
        }
        if (definition !== existing)
            throw new Error(`Duplicate latest event definition for ${definition.type}`);
        return result;
    }, new Map()));
}
export function versionedType(type, version) {
    return `${type}.${version}`;
}
export function durableMap(definitions) {
    return readonlyMap(definitions.reduce((result, definition) => {
        if (definition.durability !== "durable")
            return result;
        const key = versionedType(definition.type, definition.durable.version);
        if (result.has(key))
            throw new Error(`Duplicate durable event definition for ${key}`);
        result.set(key, definition);
        return result;
    }, new Map()));
}
function readonlyMap(map) {
    const result = Object.freeze({
        get size() {
            return map.size;
        },
        entries: () => map.entries(),
        forEach: (callback, thisArg) => map.forEach((value, key) => callback.call(thisArg, value, key, result)),
        get: (key) => map.get(key),
        has: (key) => map.has(key),
        keys: () => map.keys(),
        values: () => map.values(),
        [Symbol.iterator]: () => map[Symbol.iterator](),
    });
    return result;
}
